#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  //  int x0,y0,x1,y1;  } Queue_Line;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintLine(DefinePaint)  {  QueueP(Queue_Line);  ::MoveToEx( hDC, p->x0, p->y0, NULL );  ::LineTo  ( hDC, p->x1, p->y1 );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddLine(DefineTegs)  {  AddQueueEx(Queue_Line);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintLine;  //  STegObj obj[] =    {    { 'I', "x" , &p->x0 },    { 'I', "y" , &p->y0 },    { 'I', "x0", &p->x0 },    { 'I', "y0", &p->y0 },    { 'I', "x1", &p->x1 },    { 'I', "y1", &p->y1 },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  EDirect eDir = ParserDirect(teg[0].value);  if ( eDir == dirHorz )    p->y1 = p->y0;  else  if ( eDir == dirVert )    p->x1 = p->x0;  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~